 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.5"/></svg>'!!}</button><button data-bs-toggle="modal" data-bs-target="#goalModal" data-item="{{base64_encode(json_encode($d))}}" onclick="openGoal(this.dataset.item)" title="Edit"><svg viewBox="0 0 24 24"><path d="M12 20H5a1 1 0 0 1-1-1v-7"/><path d="m16.5 3.5 4 4L11 17l-5 1 1-5Z"/></svg></button><button data-bs-toggle="modal" data-bs-target="#progressModal" data-id="{{$g->id}}" data-progress="{{$g->progress}}" onclick="progressGoal(this)" title="Update Progress"><svg viewBox="0 0 24 24"><path d="M5 20v-6M10 20V9M15 20V4M20 20V12"/></svg></button><form method="POST" action="{{route('employee-goals-destroy',$g)}}" class="eg-delete">@csrf @method('DELETE')<button title="Delete"><svg viewBox="0 0 24 24"><path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6m5 4v7m4-7v7"/></svg></button></form></div></td></tr>@empty<tr><td colspan="8" class="text-center py-10 text-muted">No employee goals found.</td></tr>@endforelse</tbody></table></div><div class="d-flex justify-content-between p-4"><span class="text-muted">Showing {{$goals->firstItem()??0}} to {{$goals->lastItem()??0}} of {{$goals->total()}} results</span>{{$goals->links('pagination::bootstrap-4')}}</div></div></div>
<div class="modal fade" id="goalModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="goalForm" method="POST" action="{{route('employee-goals-store')}}" novalidate>@csrf<span id="goalMethod"></span><div class="modal-header"><h3 id="goalTitle">Add New Employee Goal</h3><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" style="max-height:72vh;overflow:auto">@foreach([['employee_id','Employee','select'],['goal_type_id','Goal Type','select']] as $x)<div class="mb-5"><label class="form-label required">{{$x[1]}}</label><select class="form-select" name="{{$x[0]}}"><option value="">Select {{$x[1]}}</option>@foreach($x[0]==='employee_id'?$employees:$types as $o)<option value="{{$o->id}}">{{$o->name}}</option>@endforeach</select></div>@endforeach<div class="mb-5"><label class="form-label required">Goal Title</label><input class="form-control" name="title" placeholder="e.g. Improve Customer Satisfaction"></div><div class="mb-5"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3" placeholder="Goal description..."></textarea></div><div class="mb-5"><label class="form-label required">Start Date</label><input class="form-control" type="date" name="start_date"></div><div class="mb-5"><label class="form-label required">End Date</label><input class="form-control" type="date" name="end_date"></div><div class="mb-5"><label class="form-label">Target</label><input class="form-control" name="target" placeholder="e.g. Complete 5 projects"></div><div class="mb-5"><label class="form-label">Progress (%)</label><input class="form-control" type="number" min="0" max="100" name="progress" placeholder="e.g. 50"></div><div><label class="form-label required">Status</label><select class="form-select" name="status"><option>Not Started</option><option>In Progress</option><option>Completed</option></select></div></div><div class="modal-footer"><button type="button