<div class="modal fade eg-view-modal" id="viewModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><div class="d-flex align-items-center gap-3"><span class="eg-view-title-icon"><i class="bi bi-bullseye"></i></span><h3 class="mb-0">Employee Goal Details</h3></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="eg-details">@foreach(['title'=>'Goal Title','employee'=>'Employee','type'=>'Goal Type','target'=>'Target','start_date'=>'Start Date','end_date'=>'End Date','status'=>'Status','progress'=>'Progress','description'=>'Description'] as $k=>$v)<div class="{{$k==='description'?'eg-full':''}}"><div class="eg-label">{{$v}}</div><strong data-goal-view="{{$k}}">—</strong></div>@endforeach</div></div></div></div></div><div class="modal fade" id="progressModal"><div class="modal-dialog modal-dialog-centered modal-sm"><div class="modal-content"><form id="progressForm" method="POST">@csrf @method('PATCH')<div class="modal-header"><h3>Update Goal Progress</h3><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label required">Progress (%)</label><input class="form-control" type="number" name="progress" min="0" max="100"></div><div class="modal-footer"><button class="btn btn-light" type="button" data-bs-dismiss="modal">Cancel</button><button class="btn btn-success">Save</button></div></form></div></div></div>
<script>const goalStore=@json(route('employee-goals-store')),goalUpdate=@json(route('employee-goals-update','__ID__')),progressUrl=@json(route('employee-goals-progress','__ID__'));function dataGoal(x){return x?JSON.parse(atob(x)):{} }function openGoal(x){let d=dataGoal(x),f=goalForm;f.reset();f.action=goalStore;goalMethod.innerHTML='';goalTitle.textContent=d.id?'Edit Employee Goal':'Add New Employee Goal';['employee_id','goal_type_id','title','description','start_date','end_date','target','progress','status'].forEach(k=>f.elements[k].value=d[k]??(k==='status'?'Not Started':''));if(d.id){f.action=goalUpdate.replace('__ID__',d.id);goalMethod.innerHTML='<input type="hidden" name="_method" value="PUT">'}}function viewGoal(x){let d=dataGoal(x);Object.keys(d).forEach(k=>{let e=viewModal.querySelector('[data-goal-view='+k+']');if(e)e.textContent=k==='progress'?d[k]+'%':d[k]||'—'})}function progressGoal(b){progressForm.action=progressUrl.replace('__ID__',b.dataset.id);progressForm.elements.progress.value=b.dataset.progress}document.addEventListener('DOMContentLoaded',()=>{let f=goalForm,n={employee_id:'Employee',goal_type_id:'Goal Type',title:'Goal Title',start_date:'Start Date',end_date:'End Date',status:'Status'};function v(e){let m=!e.value? n[e.name]+' is required':e.name==='end_date'&&f.elements.start_date.value&&e.value<f.elements.start_date.value?'End Date must be after or equal to Start Date':'',x=e.parentElement.querySelector('.eg-error');if(!x){x=document.createElement('div');x.className='eg-error';e.after(x)}e.classList.toggle('eg-invalid',!!m);x.textContent=m;return !m}f.onsubmit=e=>{let first;Object.keys(n).forEach(k=>{if(!v(f.elements[k])&&!first)first=f.elements[k]});if(first){e.preventDefault();first.focus()}};progressForm.onsubmit=e=>{let p=progressForm.elements.progress;if(p.value===''||p.value<0||p.value>100){e.preventDefault();Swal.fire({icon:'error',text:'Progress must be between 0 and 100'})}};document.querySelectorAll('.eg-delete').forEach(x=>x.onsubmit=e=>{if(x.dataset.ok)return;e.preventDefault();Swal.fire({title:'Delete employee goal?',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#f1416c'}).then(r=>{if(r.isConfirmed){x.dataset.ok=1;x.submit()}})})})</script><script>document.addEventListener("DOMContentLoaded",function(){let icons=["bi-bullseye","bi-person","bi-tag","bi-crosshair","bi-calendar","bi-calendar","bi-file-earmark-text","bi-bullseye","bi-file-earmark-text"];viewModal.querySelectorAll(".eg-label").forEach(function(label,i){if(!label.querySelector("i")){let icon=document.createElement("i");icon.className="bi "+icons[i];label.prepend(icon)}})});window.viewGoal=function(x){let d=dataGoal(x);Object.keys(d).forEach(function(k){let e=viewModal.querySelector("[data-goal-view="+k+"]");if(!e)return;if(k==="progress"){e.innerHTML="<span class=\"eg-view-progress\"><span style=\"width:"+d[k]+"%\"></span></span><span>"+d[k]+"%</span>"}else if(k==="status"){e.innerHTML="<span class=\"eg-badge eg-"+String(d[k]).replace(/ /g,"-")+"\">"+d[k]+"</span>"}else{e.textContent=d[k]||"—"}})}</script>@endsection
